        var updatedSounds = detectedSounds
        var newDetections: [(name: String, confidence: Double)] = []
        var reDetections: [(name: String, confidence: Double)] = []
        var changed = false

        for (soundIdentifier, detectionState) in states {
            let clampedConfidence = min(1.0, max(0.0, detectionState.currentConfidence))

            guard detectionState.isDetected && selectedSounds.contains(soundIdentifier) else { continue }

            let alreadyDetected = updatedSounds.contains(where: { $0.soundIdentifier == soundIdentifier })
            if !alreadyDetected {
                let newDetectedSound = DetectedSound(
                    soundIdentifier: soundIdentifier,
                    detectedAt: currentTime,
                    confidence: clampedConfidence
                )
                updatedSounds.append(newDetectedSound)
