    // Keys for widget shared data
    private enum WidgetKeys {
        static let isDetecting = "widget_isDetecting"
        static let lastSound = "widget_lastSound"
        static let lastSoundTime = "widget_lastSoundTime"
        static let recentSounds = "widget_recentSounds"
    }

    // Sync current state to shared UserDefaults for widgets.
    // Public entry point — acquires cacheQueue for thread safety.
    static func syncToWidget() {
        let history = cacheQueue.sync { getCachedTapsHistory() }
        syncToWidgetInternal(history: history)
    }

    // Internal: called from within cacheQueue.sync (recordTap) or with pre-fetched history.
    // Avoids data race by not accessing cachedTapsHistory directly.
    private static func syncToWidgetInternal(history: [TapRecord]) {
        let defaults = sharedDefaults
        defaults.set(soundDetectionState, forKey: WidgetKeys.isDetecting)

        if let lastSound = history.last {
            defaults.set(lastSound.soundName, forKey: WidgetKeys.lastSound)
            defaults.set(lastSound.timestamp, forKey: WidgetKeys.lastSoundTime)
        }

        let recentSounds = Array(history.suffix(5))
        if let encoded = try? widgetEncoder.encode(recentSounds) {
            defaults.set(encoded, forKey: WidgetKeys.recentSounds)
        }

        // Throttle widget reload to once per 60 seconds
        let now = CFAbsoluteTimeGetCurrent()
        if now - lastWidgetReloadTime >= widgetReloadInterval {
            lastWidgetReloadTime = now
            WidgetCenter.shared.reloadAllTimelines()
        }
    }

    // Called from widgets to read data
    static func getWidgetData() -> WidgetData {
        let defaults = sharedDefaults

        let isDetecting = defaults.bool(forKey: WidgetKeys.isDetecting)
        let lastSound = defaults.string(forKey: WidgetKeys.lastSound)
        let lastSoundTime = defaults.double(forKey: WidgetKeys.lastSoundTime)

        var recentSounds: [TapRecord] = []
        if let data = defaults.data(forKey: WidgetKeys.recentSounds),
           let decoded = try? JSONDecoder().decode([TapRecord].self, from: data) {
            recentSounds = decoded
        }

        return WidgetData(
            isDetecting: isDetecting,
            lastSound: lastSound,
            lastSoundTime: lastSoundTime > 0 ? Date(timeIntervalSince1970: lastSoundTime) : nil,
            recentSounds: recentSounds
        )
    }

    // Toggle detection state (for interactive widget)
    static func toggleDetectionFromWidget() {
        // This will be called from the widget - the main app should handle the actual toggle
        let newState = !sharedDefaults.bool(forKey: WidgetKeys.isDetecting)
        sharedDefaults.set(newState, forKey: "widget_requestedState")
        sharedDefaults.set(true, forKey: "widget_stateChangeRequested")
    }
