/// Child views access environment objects via their own @EnvironmentObject declarations.
struct ContentView: View {
    @Binding var isLoadingAudio: Bool
    var isHomeTabVisible: Bool = true

    var body: some View {
        SetupMonitoredSoundsView(
            querySoundOptions: { return try AppConfiguration.listAllValidSoundIdentifiers() },
            isLoadingAudio: $isLoadingAudio
        )
        .environment(\.isHomeTabVisible, isHomeTabVisible)
        .localizedView()
    }
}

// Environment key for passing tab visibility without modifying SetupMonitoredSoundsView's init
private struct HomeTabVisibleKey: EnvironmentKey {
    static let defaultValue: Bool = true
}

extension EnvironmentValues {
    var isHomeTabVisible: Bool {
        get { self[HomeTabVisibleKey.self] }
        set { self[HomeTabVisibleKey.self] = newValue }
    }
}

