import Foundation

class AudioEngineManager {
    static let shared = AudioEngineManager()

    private var activeComponent: AudioEngineUser?

    private init() {}

    /// Sets the active audio engine component, ensuring no conflicts.
    func setActiveComponent(_ component: AudioEngineUser) {
        if activeComponent !== component {
            activeComponent?.stopAudioEngine()
            activeComponent = component
        }
    }

    /// Clears the active component reference (call when a component fully stops).
    func clearActiveComponent(_ component: AudioEngineUser) {
        if activeComponent === component {
            activeComponent = nil
        }
    }
}

